# =============================================================================
# L2 · 符号隔离 —— version script（链接器导出表）
# =============================================================================
# 硬规则第 2 条：每个 .so 上只导出 JNI_OnLoad，其余全部 hidden。
#
# 为什么这不是洁癖，而是必须：
#   MNN 与 llama.cpp **都**带 OpenCL / Vulkan 后端，且都静态链入了各自的
#   ggml / MNN 引擎实现与第三方库（half、OpenCL headers、Vulkan loader 包装…）。
#   两个 .so 被同一个进程 dlopen 时，动态链接器按加载顺序解析全局符号 ——
#   先加载的那个的同名符号会把后加载的**覆盖**掉。
#
#   典型症状极难查：MNN 的 GPU 后端莫名调用到 llama 的 ggml 符号，
#   表现为「开了 GPU 就崩、关了就正常」，而两边的代码都"没问题"。
#
#   把导出表收敛到 1 个符号后，跨 .so 的符号竞争面直接归零。
#
# 验收命令（必须真跑，不能只看 CMake 配置）：
#   llvm-nm -D --defined-only libquro_llm_mnn.so | grep -v ' JNI_OnLoad$'
#   期望：除 JNI_OnLoad 外无任何 T/D/B/W 导出符号。
#
# 注：`local: *;` 是必须的兜底 —— 只写 global 段的话，未列出的符号默认仍是
#     default visibility，等于没隔离。这是最容易写漏的一行。
# =============================================================================
{
  global:
    # 唯一对外可见的入口：JVM 加载 .so 时调用它做 RegisterNatives。
    JNI_OnLoad;

  local:
    # 其余全部隐藏（含 .so 内部互相调用的辅助函数、以及静态链入的
    # ggml / MNN / OpenCL / Vulkan 包装符号）。
    *;
};
